begin;
select set_config('request.jwt.claim.sub',(select id::text from auth.users order by created_at limit 1),true);
set local role authenticated;
do $$
#variable_conflict use_variable
declare suffix text:=upper(gen_random_uuid()::text); client uuid; goods uuid; service uuid; document uuid:=gen_random_uuid(); second uuid:=gen_random_uuid(); only_service uuid:=gen_random_uuid(); draft jsonb; version integer; doc_number integer; rejected boolean; snapshot jsonb; initial_stock integer;
begin
 insert into public.business_clients(name,address,city,vat_number) values('QA Company '||suffix,'Via di prova 1','Comune prova','QA'||suffix) returning id into client;
 goods:=public.save_catalogue_product(null,jsonb_build_object('internal_code','QA-DDT-'||suffix,'name','Ricambio prova','stockQuantity',10));
 service:=public.save_catalogue_product(null,jsonb_build_object('internal_code','QA-SRV-'||suffix,'name','Manodopera prova','kind','service','unit','ore'));
 if (select kind from public.products where id=service)<>'service' then raise exception 'FAIL: service catalogue type'; end if;
 draft:=jsonb_build_object('client_id',client,'document_date',current_date,'vehicle','{}'::jsonb,'delivery_address','Via di prova 1','transport_reason','Vendita','lines',jsonb_build_array(jsonb_build_object('product_id',goods,'description','Ricambio','quantity','1','unit_price','180','discount','10'),jsonb_build_object('product_id',service,'description','Manodopera','quantity','2','unit_price','42.70','discount','0')));
 perform public.save_delivery_document(document,draft,null);
 if (select total from public.delivery_documents where id=document)<>247.40 then raise exception 'FAIL: exact mixed document total'; end if;
 rejected:=false;begin perform public.save_delivery_document(document,draft,null);exception when raise_exception then rejected:=true;end;
 if not rejected then raise exception 'FAIL: repeated create/stale save guard'; end if;
 rejected:=false;begin perform public.issue_delivery_document(document,1);exception when raise_exception then rejected:=true;end;
 if not rejected then raise exception 'FAIL: administrative validation gate'; end if;
 update public.delivery_settings set name='QA Officina',address='Via prova 2',city='Comune prova',vat_number='QA'||suffix,fiscal_verified=true where id=true;
 perform public.issue_delivery_document(document,1);
 select number,client_snapshot into doc_number,snapshot from public.delivery_documents where id=document;
 perform public.issue_delivery_document(document,1);
 if (select number from public.delivery_documents where id=document)<>doc_number then raise exception 'FAIL: repeated emission idempotent'; end if;
 if (select stock_quantity from public.products where id=goods)<>10 then raise exception 'FAIL: DDT must not change stock'; end if;
 rejected:=false;begin perform public.save_delivery_document(document,draft,2);exception when raise_exception then rejected:=true;end;
 if not rejected then raise exception 'FAIL: issued document immutable'; end if;
 rejected:=false;begin update public.delivery_documents set total=1 where id=document;exception when insufficient_privilege then rejected:=true;end;
 if not rejected then raise exception 'FAIL: client cannot bypass validation'; end if;
 update public.business_clients set name='Changed company' where id=client;
 delete from public.products where id=goods;
 if (select client_snapshot from public.delivery_documents where id=document)<>snapshot or (select total from public.delivery_documents where id=document)<>247.40 then raise exception 'FAIL: immutable snapshots after catalogue/client edits'; end if;
 perform public.cancel_delivery_document(document,'Documento di prova annullato',2);
 perform public.cancel_delivery_document(document,'Second retry',2);
 if (select status from public.delivery_documents where id=document)<>'void' or (select cancellation_reason from public.delivery_documents where id=document)<>'Documento di prova annullato' then raise exception 'FAIL: cancellation preserves original reason'; end if;
 draft:=jsonb_set(draft,'{lines}',jsonb_build_array(jsonb_build_object('product_id',service,'description','Solo manodopera','quantity','2.5','unit_price','35','discount','12.5')));
 perform public.save_delivery_document(only_service,draft,null);
 if (select kind from public.delivery_documents where id=only_service)<>'work' or (select total from public.delivery_documents where id=only_service)<>76.56 then raise exception 'FAIL: service document and rounding'; end if;
 perform public.issue_delivery_document(only_service,1);
 perform public.save_delivery_document(second,draft,null);
 perform public.delete_delivery_draft(second,1);
 if exists(select 1 from public.delivery_documents where id=second) then raise exception 'FAIL: draft deletion'; end if;
 rejected:=false;begin perform public.save_delivery_document(second,jsonb_set(draft,'{lines}','[]'),null);exception when raise_exception then rejected:=true;end;
 if not rejected then raise exception 'FAIL: empty lines'; end if;
 rejected:=false;begin perform public.save_delivery_document(second,jsonb_set(draft,'{lines}',jsonb_build_array(jsonb_build_object('product_id',service,'description','Wrong','quantity','1','unit_price','10','discount','101'))),null);exception when raise_exception then rejected:=true;end;
 if not rejected then raise exception 'FAIL: discount validation'; end if;
 rejected:=false;begin perform public.save_delivery_document(second,draft-'lines',null);exception when raise_exception then rejected:=true;end;
 if not rejected then raise exception 'FAIL: missing lines'; end if;
 delete from public.business_clients where id=client;
 if (select client_id from public.delivery_documents where id=document) is not null or (select client_snapshot from public.delivery_documents where id=document)<>snapshot then raise exception 'FAIL: client deletion preserves documents'; end if;
 if has_function_privilege('anon','public.issue_delivery_document(uuid,integer)','execute') then raise exception 'FAIL: anonymous emission'; end if;
end; $$;
rollback;
select 'OK: mixed and services, exact prices/discounts, snapshots, idempotent numbering, immutable documents, cancellation, deletion, missing data and access control' as result;
